(* async_reg = "true" *) reg rs0, rs1;
always @(posedge ck or negedge rst_n)
    if (!rst_n) begin rs0<=1'b0;rs1<=1'b0;end

// QC-CORES-1 10-27 (rst3 KEEP-FAIL fix): lane 0 has multiplier K=0, so qfd_dv_su8_stride #(0) is y=0 and
// xs_l[0] can only ever load 0 -> its 16 select replicas g_xsl[0].g_sel[*] and the K=0 xlane register were dead
// logic (yosys const-folded g_xsl[0].u.q, ORFS 1_synth eliminate_dead_logic then removed the 16 kept-but-unloaded
// kff instances -> routed LEC KEEP FAIL 16/3254).  Lane 0 is now the constant it already was (power-up X of the
// never-loaded-nonzero register refined to 0, as synthesis and the LEC gold already did); lanes 1..7 keep their
// names g_xsl[1..7].* unchanged.  0 edges, same values.
assign xs_l[0] = {4*AW{1'b0}};
for (gc = 1; gc < 8; gc = gc + 1) begin : g_xsl

reg  [FAW-1:0] fa;
integer fi;
always @(posedge ck)
    for (fi = 0; fi < FAW; fi = fi + 1) if (acc_k[fi / FCW]) fa[fi] <= fa_in[fi];

wire [FAW-1:0] fa;
// Nvec is ceil(nin/8), at most 32768 for any 18bit nin; bits17:16 are structuralzero.
genvar fi;
generate for (fi = 0; fi < FAW; fi = fi + 1) begin : g_fa_payload
    if (fi == 332 || fi == 333) begin : g_zero
        assign fa[fi] = 1'b0;
    end else begin : g_live
        reg payload;
        always @(posedge ck) if (acc_k[fi / FCW]) payload <= fa_in[fi];
        assign fa[fi] = payload;
    end
end endgenerate

integer c;
always @(posedge ck)
    for (c = 0; c < 16; c = c + 1) if (sel[c]) q[6*c +: 6] <= m[6*c +: 6];

// Multiplication by constant K has exactzero trailingbits; only payloadbits require storage.
genvar b;
generate for (b = 0; b < 96; b = b + 1) begin : g_payload
    if ((K % (1 << ((b % 24) + 1))) == 0) begin : g_zero
        assign q[b] = 1'b0;
    end else begin : g_live
        reg payload;
        always @(posedge ck) if (sel[b / 6]) payload <= m[b];
        assign q[b] = payload;
    end
end endgenerate
